private byte[] bytes(String name) throws IOException {
  if (name.startsWith("com/liucodex/") || name.startsWith("mixins.") && name.endsWith(".json")) {
    byte[] data;
    String archive = System.getProperty("dnv.artifact");
    if (archive != null && !archive.isBlank()) {
      try (ZipFile artifact = new ZipFile(archive)) {
        var entry = artifact.getEntry(name);
        if (entry == null) throw new IOException("Missing production artifact member: " + name);
        data = artifact.getInputStream(entry).readAllBytes();
      }
    } else {
      String property = name.endsWith(".class") ? "dnv.production.classDirs" : "dnv.production.resourceDirs";
      String roots = System.getProperty(property);
      if (roots == null || roots.isBlank()) throw new IOException("Missing current production input: " + property);
      Path found = null;
      for (String directory : roots.split(java.util.regex.Pattern.quote(java.io.File.pathSeparator))) {
        Path candidate = Path.of(directory, name);
        if (Files.isRegularFile(candidate)) {
          if (found != null) throw new IOException("Duplicate production member: " + name);
          found = candidate;
        }
      }
      if (found == null) throw new IOException("Missing current compiled/resource member: " + name);
      data = Files.readAllBytes(found);
    }
    if (name.startsWith("mixins.") && name.endsWith(".json")) {
      var config = JsonParser.parseString(new String(data, StandardCharsets.UTF_8)).getAsJsonObject();
      for (String side : List.of("mixins", "client")) {
        JsonArray selected = new JsonArray();
        if (config.has(side)) for (var value : config.getAsJsonArray(side))
          if (value.getAsString().equals(selectedMixin)
              || selectedMixin.equals("ApocalypseClientFireMixin") && value.getAsString().equals("DragonClientPredictionMixin")
              || cameraArtifact!=null && (value.getAsString().equals("BlizzardCameraAccess")
                  || value.getAsString().equals("BlizzardCameraFrameMixin"))) selected.add(value);
        config.add(side, selected);
      }
      return config.toString().getBytes(StandardCharsets.UTF_8);
    }
    return data;
  }
  // Platform classes cannot come from an embedded mod library; avoid inflating every nested JAR for each hierarchy lookup.
  if (name.startsWith("net/minecraft/") || name.startsWith("java/")) {
    try (InputStream platform = getClass().getClassLoader().getResourceAsStream(name)) {
      if (platform != null) return platform.readAllBytes();
    }
  }
  try (ZipFile sbw = new ZipFile(System.getProperty("dnv.sbw.jar"))) {
    var entry = sbw.getEntry(name);
    if (entry != null) return sbw.getInputStream(entry).readAllBytes();
    for (var candidate : sbw.stream().filter(e -> e.getName().startsWith("META-INF/jarjar/") && e.getName().endsWith(".jar")).toList()) {
      try (ZipInputStream nested = new ZipInputStream(sbw.getInputStream(candidate))) {
        for (var part = nested.getNextEntry(); part != null; part = nested.getNextEntry())
          if (part.getName().equals(name)) return nested.readAllBytes();
      }
    }
  }
  try (InputStream stream = getClass().getClassLoader().getResourceAsStream(name)) {
    if (stream == null) throw new IOException(name);
    return stream.readAllBytes();
  }
}

